#include "../../native/AudioPcm.h"
#include <iostream>
#include <vector>
int main(){for(int bits:{16,24,32})for(bool floating:{false,true}){if(floating&&bits!=32)continue;WAVEFORMATEX format{};format.wFormatTag=floating?WAVE_FORMAT_IEEE_FLOAT:WAVE_FORMAT_PCM;format.nChannels=2;format.nSamplesPerSec=48000;format.wBitsPerSample=bits;format.nBlockAlign=2*bits/8;slop_pcm::validate(&format);float source[]={-1,-.5f,-.1f,0,.1f,.5f,1,0};std::vector<BYTE> bytes(8*bits/8);float restored[8]{};slop_pcm::encode(source,bytes.data(),8,&format);slop_pcm::decode(bytes.data(),restored,8,&format);for(int i=0;i<8;i++)if(std::abs(restored[i]-source[i])>(bits==16?.00007:.0000003)){std::cerr<<"FAIL PCM "<<bits<<" sample "<<i;return 1;}std::cout<<"PASS "<<bits<<(floating?"-bit float":"-bit PCM")<<" signed stereo encode / decode\n";}WAVEFORMATEXTENSIBLE extended{};extended.Format.wFormatTag=WAVE_FORMAT_EXTENSIBLE;extended.Format.nChannels=2;extended.Format.wBitsPerSample=32;extended.Format.nBlockAlign=8;extended.Format.cbSize=22;extended.SubFormat=slop_pcm::PcmSubtype;extended.Samples.wValidBitsPerSample=24;slop_pcm::validate(&extended.Format);if(slop_pcm::floating(&extended.Format))return 2;std::cout<<"PASS WAVEFORMATEXTENSIBLE PCM32 / valid 24-bit classification\n";return 0;}
